function validate([grid]) {
  if (!Array.isArray(grid) || grid.length < 2 || grid.length > 300) return 'grid needs 2 to 300 rows.';
  const n = Array.isArray(grid[0]) ? grid[0].length : 0;
  if (n < 2 || n > 300) return 'Each row needs 2 to 300 cells.';
  if (grid.length * n > 20000) return 'grid can have at most 20000 cells.';
  for (const row of grid) {
    if (!Array.isArray(row) || row.length !== n) return 'All rows must have the same length.';
    if (row.some(v => v !== 0 && v !== 1 && v !== 2)) return 'Each cell is 0, 1 or 2.';
  }
  if (grid[0][0] !== 0 || grid[grid.length - 1][n - 1] !== 0) return 'The top-left and bottom-right cells must be grass (0).';
  return null;
}

