function maximumMinutes(grid) {
  const rows = grid.length;
  const cols = grid[0].length;
  const directions = [[1, 0], [-1, 0], [0, 1], [0, -1]];

  const bfs = (sources) => {
    const time = Array.from({ length: rows }, () => new Array(cols).fill(Infinity));
    const queue = [];
    for (const [r, c] of sources) {
      time[r][c] = 0;
      queue.push([r, c]);
    }
    for (let head = 0; head < queue.length; head++) {
      const [r, c] = queue[head];
      for (const [dr, dc] of directions) {
        const nr = r + dr;
        const nc = c + dc;
        if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) continue;
        if (grid[nr][nc] !== 0 || time[nr][nc] !== Infinity) continue;
        time[nr][nc] = time[r][c] + 1;
        queue.push([nr, nc]);
      }
    }
    return time;
  };

  const fires = [];
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      if (grid[r][c] === 1) fires.push([r, c]);
    }
  }
  const fire = bfs(fires);
  const person = bfs([[0, 0]]);

  const arrive = person[rows - 1][cols - 1];
  const burn = fire[rows - 1][cols - 1];
  if (arrive === Infinity) return -1;
  if (burn === Infinity) return 1e9;
  const slack = burn - arrive;
  if (slack < 0) return -1;

  for (const [r, c] of [[rows - 2, cols - 1], [rows - 1, cols - 2]]) {
    if (person[r][c] !== Infinity && fire[r][c] - person[r][c] > slack) {
      return slack;
    }
  }
  return slack - 1;
}

