function maximumMinutes(grid) {
  const m = grid.length, n = grid[0].length;
  const steps = [[1, 0], [-1, 0], [0, 1], [0, -1]];
  const inside = (r, c) => r >= 0 && r < m && c >= 0 && c < n;
  // Simulate waiting `wait` minutes, then walking, minute by minute.
  const survives = wait => {
    let burning = grid.map(row => row.map(v => v === 1));
    const spread = () => {
      const next = burning.map(row => row.slice());
      for (let r = 0; r < m; r++) for (let c = 0; c < n; c++) {
        if (!burning[r][c]) continue;
        for (const [dr, dc] of steps) {
          const a = r + dr, b = c + dc;
          if (inside(a, b) && grid[a][b] !== 2) next[a][b] = true;
        }
      }
      burning = next;
    };
    for (let i = 0; i < wait; i++) {
      spread();
      if (burning[0][0]) return false;
    }
    const visited = grid.map(row => row.map(() => false));
    visited[0][0] = true;
    let here = [[0, 0]];
    while (here.length > 0) {
      const moved = [];
      for (const [r, c] of here) for (const [dr, dc] of steps) {
        const a = r + dr, b = c + dc;
        if (!inside(a, b) || visited[a][b] || grid[a][b] === 2 || burning[a][b]) continue;
        if (a === m - 1 && b === n - 1) return true;
        visited[a][b] = true;
        moved.push([a, b]);
      }
      spread();
      here = moved.filter(([r, c]) => !burning[r][c]);
    }
    return false;
  };
  // After m * n minutes the fire can no longer grow, so waiting that long works only if any wait works.
  if (survives(m * n)) return 1e9;
  let best = -1;
  for (let wait = 0; wait < m * n; wait++) if (survives(wait)) best = wait;
  return best;
}

