function generate(rand, size) {
  const large = size === 'large';
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const fuse = rand() < (large ? 0.8 : 0.6);
  const width = large ? pick(5, 30) : pick(2, 4);
  const m = large ? pick(60, 100) : pick(fuse ? 4 : 2, 7);
  const n = large ? pick(60, 100) : fuse ? width + pick(2, 3) : pick(2, 7);
  const wallRate = large ? rand() * 0.25 : rand() * 0.35;
  const grid = Array.from({ length: m }, () => Array.from({ length: n }, () => (rand() < wallRate ? 2 : 0)));
  // Carve a right/down path so the safehouse is usually reachable.
  const right = fuse ? n - width - 2 : n - 1;
  if (fuse || rand() < 0.8) {
    let r = 0, c = 0;
    while (r < m - 1 || c < right) {
      grid[r][c] = 0;
      if (r === m - 1) c++;
      else if (c === right) r++;
      else if (rand() < 0.5) r++;
      else c++;
    }
  }
  let fires = large ? pick(0, 2) : pick(0, 2);
  if (fuse) {
    // A walled-off winding fuse on the right carries fire down to the bottom row the long way round.
    const left = n - width;
    for (let c = 0; c < n; c++) grid[m - 1][c] = 0;
    for (let r = 0; r < m - 1; r++) {
      grid[r][left - 1] = 2;
      for (let c = left; c < n; c++) grid[r][c] = 0;
      if (r % 2 === 1) {
        const gap = (r >> 1) % 2 === 0 ? n - 1 : left;
        for (let c = left; c < n; c++) if (c !== gap) grid[r][c] = 2;
      }
    }
    if (!large && rand() < 0.7) grid[0][left] = 1;
    else grid[2 * pick(0, Math.floor((m - 2) / 2))][pick(left, n - 1)] = 1;
    fires = rand() < 0.25 ? 1 : 0;
  }
  for (let i = 0; i < fires; i++) {
    const r = pick(0, m - 1), c = pick(0, n - 1);
    if (grid[r][c] !== 2 && r + c >= (large ? (m + n) / 2 : 1)) grid[r][c] = 1;
  }
  grid[0][0] = 0;
  grid[m - 1][n - 1] = 0;
  return [grid];
}
